// 从不可变初态逐笔应用经过原业务证明的差量，再与唯一Common实物对账；查询无副作用。
#include "growth_market_history.hpp"
#include "growth_model.hpp"
#include "growth_market_history_codec.hpp"
#include "growth_market_history_v2_read.hpp"
#include <algorithm>
#include <charconv>
#include <map>
#include <set>
namespace hanmo::resident {namespace {
bool identity_equal(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool same_order(const FieldOrder& a,const FieldOrder& b,const FieldOrder& canonical){return (a.empty()?canonical:a)==(b.empty()?canonical:b);}
bool lot_equal(const LotView& a,const LotView& b){return a.id==b.id&&a.item_id==b.item_id&&a.quantity==b.quantity&&owner_equal(a.owner,b.owner)&&a.reserved_by==b.reserved_by&&!a.extra&&!b.extra&&same_order(a.field_order,b.field_order,{"id","item_id","quantity","owner","reserved_by"});}
bool inventory_equal(const InventoryView& a,const InventoryView& b){if(a.id!=b.id||!owner_equal(a.owner,b.owner)||a.capacity!=b.capacity||a.revision!=b.revision||!same_order(a.field_order,b.field_order,{"id","owner","capacity","revision","lots"})||a.lots.size()!=b.lots.size())return false;for(std::size_t i=0;i<a.lots.size();++i)if(!lot_equal(a.lots[i],b.lots[i]))return false;return true;}
bool change_equal(const MarketInventoryChange& a,const MarketInventoryChange& b){if(a.inventory_id!=b.inventory_id||a.revision_before!=b.revision_before||a.revision_after!=b.revision_after||a.lots.size()!=b.lots.size())return false;for(std::size_t i=0;i<a.lots.size();++i){const auto& x=a.lots[i];const auto& y=b.lots[i];if(x.lot_id!=y.lot_id||bool(x.before)!=bool(y.before)||bool(x.after)!=bool(y.after)||(x.before&&!lot_equal(*x.before,*y.before))||(x.after&&!lot_equal(*x.after,*y.after)))return false;}return true;}
Integer ordinal(const StableId& id,const StableId& prefix){const auto key=prefix+":";if(id.rfind(key,0)!=0)return -1;const auto digits=id.substr(key.size());Integer n=0;auto p=std::from_chars(digits.data(),digits.data()+digits.size(),n);return p.ec==std::errc{}&&p.ptr==digits.data()+digits.size()&&n>0&&std::to_string(n)==digits?n:-1;}
std::size_t pos(const CommonStore& c,const StableId& id){const auto& order=c.state().facts.order();return std::size_t(std::find(order.begin(),order.end(),id)-order.begin());}
StableId source_kind(MarketCauseKind kind){return kind==MarketCauseKind::growth_trade?"life_activity":kind==MarketCauseKind::local_production?"local_production":kind==MarketCauseKind::local_ration?"local_ration":"";}
// 每一种原业务只有固定recipe阶段；按原有序腿派生本次受保护容器的原语次数。
std::vector<std::pair<MarketCaptureStage,MarketRecipeInspection>> expected_steps(const ProtectedMarketAccounts& policy,const MarketBusinessCause& cause){
    std::vector<std::pair<MarketCaptureStage,MarketRecipeInspection>> out;
    const std::vector<MarketCaptureStage> stages=cause.kind==MarketCauseKind::growth_trade?std::vector<MarketCaptureStage>{MarketCaptureStage::trade}:cause.kind==MarketCauseKind::local_production?std::vector<MarketCaptureStage>{MarketCaptureStage::production_inputs,MarketCaptureStage::production_outputs}:std::vector<MarketCaptureStage>{MarketCaptureStage::ration};
    for(auto stage:stages){MarketRecipeInspection result;for(const auto& leg:cause.legs){if(!policy.inventories.find(leg.inventory_id)||(stage==MarketCaptureStage::production_inputs&&leg.signed_quantity>0)||(stage==MarketCaptureStage::production_outputs&&leg.signed_quantity<0))continue;auto at=std::find_if(result.inventories.begin(),result.inventories.end(),[&](const auto& x){return x.inventory_id==leg.inventory_id;});if(at==result.inventories.end()){result.inventories.push_back({leg.inventory_id});at=std::prev(result.inventories.end());}at->legs.push_back(leg);if(leg.signed_quantity>0)++at->add_operations;else ++at->consume_operations;at->fragmented_adds=cause.kind==MarketCauseKind::growth_trade;}
        if(!result.inventories.empty())out.emplace_back(stage,std::move(result));
    }return out;
}
struct Replay {OrderedTable<InventoryView> current,before;};
// 完整尾仍须与当前Common核等，历史query只另留精确边界之前的临时投影。
Outcome<Replay> replay(const CommonStore& c,const CommonCatalog& common,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,const GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access,const StableId& boundary,Integer observed){
    auto bad=[](const StableId& code,const StableId& id=StableId{})->Outcome<Replay>{return {false,{},common_failure(code,id).error};};
    auto structure=validate_growth_market_history_shape(state);if(!structure.ok)return {false,{},structure.error};
    if(!growth.regional_life||!growth.economy||!access.source_ids||catalog.shop_ids.empty()||catalog.initial_inventories.empty()||catalog.initial_next_instance_id<1||catalog.initial_next_instance_id>c.state().next_instance_id)return bad("GrowthMarketHistoryProfileRequired");
    const auto cutoff=boundary.empty()?c.state().facts.size():pos(c,boundary);if(!boundary.empty()){const auto* h=c.state().facts.find(boundary);auto n=ordinal(boundary,"private_shop_day");if(!h||h->id!=boundary||h->kind!="private_shop_operating_completed"||h->domain!="private_shops"||n<1||n>=c.state().next_instance_id||cutoff==c.state().facts.size()||observed<0||observed>c.tick())return bad("GrowthMarketHistoryBoundaryInvalid",boundary);}
    ProtectedMarketAccounts protection;std::vector<StableId> inventory_ids;std::set<StableId> shops,initial_lots;
    for(const auto& id:catalog.shop_ids){const auto* shop=growth.shops.find(id);if(!shops.insert(id).second||!shop||!catalog.initial_inventories.find(shop->inventory_id))return bad("GrowthMarketInitialSelectionInvalid",id);}
    for(const auto& row:catalog.initial_inventories.rows()){const auto& inv=row.second;const auto* required=common.required_inventories.find(row.first);if(!required||inv.id!=row.first||!owner_equal(required->owner,inv.owner)||required->capacity!=inv.capacity||inv.revision<0)return bad("GrowthMarketInitialSourceInvalid",row.first);Integer uses=0;for(const auto& id:catalog.shop_ids)uses+=growth.shops.find(id)->inventory_id==row.first;if(uses!=1)return bad("GrowthMarketInitialSelectionInvalid",row.first);for(const auto& actor:c.state().actors.rows())if(actor.second.inventory_id==row.first)return bad("GrowthMarketNotDedicated",row.first);
        for(const auto& lot:inv.lots){auto n=ordinal(lot.id,"lot");if(n<1||n>=catalog.initial_next_instance_id||!initial_lots.insert(lot.id).second||lot.quantity<=0||!common.items.find(lot.item_id)||!owner_equal(lot.owner,inv.owner)||!lot.reserved_by.empty())return bad("GrowthMarketInitialLotInvalid",lot.id);}protection.inventories.insert(row.first,*required);inventory_ids.push_back(row.first);
    }
    auto required_sources=access.source_ids(inventory_ids);if(!required_sources.ok)return {false,{},required_sources.error};std::set<StableId> expected_sources(required_sources.value.begin(),required_sources.value.end());if(expected_sources.size()!=required_sources.value.size())return bad("GrowthMarketDuplicateCauseEnumeration");
    Replay out{catalog.initial_inventories,catalog.initial_inventories};std::set<StableId> used_sources,seen_headers;std::size_t last_source=0,last_receipt=0;bool first=true;Integer last_observed=0,next_floor=catalog.initial_next_instance_id;
    for(const auto& id:c.state().facts.order()){
        const auto* record=state.movements.find(id);const auto* head=c.state().facts.find(id);if(!record){if(head&&head->domain=="growth_market_history")return bad("GrowthMarketMovementPayloadMissing",id);continue;}
        auto n=ordinal(id,"market_history");if(!head||head->id!=id||head->kind!="growth_market_movement"||head->domain!="growth_market_history"||record->kind!=head->kind||n<1||n>=c.state().next_instance_id||!seen_headers.insert(id).second||!used_sources.insert(record->business_fact_id).second||!expected_sources.count(record->business_fact_id))return bad("GrowthMarketMovementSourceInvalid",id);
        const auto source_at=pos(c,record->business_fact_id),at=pos(c,id);const auto* source_head=c.state().facts.find(record->business_fact_id);const auto kind=source_kind(record->business_kind);if(kind.empty()||!source_head||source_head->id!=record->business_fact_id||source_head->kind!=kind||source_head->domain!=(record->business_kind==MarketCauseKind::growth_trade?"growth":"local_economy")||source_at>=at||(!first&&(source_at<=last_source||source_at<=last_receipt)))return bad("GrowthMarketMovementOrderInvalid",id);
        auto original=access.causes.market_business_cause(record->business_kind,record->business_fact_id);if(!original.ok)return {false,{},original.error};const auto& cause=original.value;if(!identity_equal(c.state().identity,cause.source_identity)||cause.source_fact_id!=record->business_fact_id||cause.kind!=record->business_kind||cause.source_tick!=record->source_tick||record->observed_tick<last_observed||record->observed_tick<0||record->observed_tick>c.tick()||(record->business_kind!=MarketCauseKind::growth_trade&&record->observed_tick==INT64_MAX)||record->source_tick!=(record->business_kind==MarketCauseKind::growth_trade?record->observed_tick:record->observed_tick+1))return bad("GrowthMarketCauseMismatch",id);
        if(cause.kind==MarketCauseKind::growth_trade){const InventoryView* market=nullptr;for(const auto& leg:cause.legs)if(const auto* inv=out.current.find(leg.inventory_id)){if(market&&market->id!=inv->id)return bad("GrowthMarketTradeNotDedicated",id);market=inv;}if(!market||!access.trade_before)return bad("GrowthMarketTradeHistoryReadRequired",id);auto valid=access.trade_before(record->business_fact_id,*market);if(!valid.ok)return {false,{},valid.error};}
        for(const auto& leg:cause.legs)if(leg.inventory_id.empty()||leg.item_id.empty()||leg.signed_quantity==0||leg.signed_quantity==INT64_MIN)return bad("GrowthMarketCauseLegInvalid",id);auto stages=expected_steps(protection,cause);if(stages.empty()||stages.size()!=record->steps.size())return bad("GrowthMarketCaptureStagesMismatch",id);
        for(std::size_t i=0;i<stages.size();++i){const auto& step=record->steps[i];const auto& wanted=stages[i];if(step.stage!=wanted.first||step.inventories.size()!=wanted.second.inventories.size()||step.next_instance_before<next_floor||step.next_instance_after<step.next_instance_before||step.next_instance_after>n)return bad("GrowthMarketCaptureBoundaryInvalid",id);
            for(std::size_t k=0;k<step.inventories.size();++k){const auto& change=step.inventories[k];const auto& touch=wanted.second.inventories[k];auto* current=out.current.find(touch.inventory_id);if(!current||change.inventory_id!=touch.inventory_id||change.revision_before!=current->revision)return bad("GrowthMarketCaptureInventoryMismatch",id);auto after=*current;std::set<StableId> changed;
                for(const auto& delta:change.lots){if(!changed.insert(delta.lot_id).second||(!delta.before&&!delta.after)||(delta.before&&delta.before->id!=delta.lot_id)||(delta.after&&delta.after->id!=delta.lot_id))return bad("GrowthMarketLotDeltaInvalid",id);auto at_lot=std::find_if(after.lots.begin(),after.lots.end(),[&](const auto& lot){return lot.id==delta.lot_id;});if(delta.before){if(at_lot==after.lots.end()||!lot_equal(*at_lot,*delta.before))return bad("GrowthMarketLotPredecessorMismatch",delta.lot_id);if(delta.after)*at_lot=*delta.after;else after.lots.erase(at_lot);}else{if(at_lot!=after.lots.end())return bad("GrowthMarketDuplicateLot",delta.lot_id);after.lots.push_back(*delta.after);}}
                after.revision=change.revision_after;auto captured=capture_protected_market_inventory(protection,touch,*current,after,step.next_instance_before,step.next_instance_after);if(!captured.ok)return {false,{},captured.error};if(!change_equal(captured.value,change))return bad("GrowthMarketNoncanonicalDelta",id);*current=std::move(after);
            }next_floor=step.next_instance_after;
        }
        if(at<cutoff){if(!boundary.empty()&&record->observed_tick>observed)return bad("GrowthMarketHistoricalClockMismatch",id);out.before=out.current;}else if(source_at<cutoff)return bad("GrowthMarketIncompleteBoundary",id);
        next_floor=n+1;first=false;last_source=source_at;last_receipt=at;last_observed=record->observed_tick;
    }
    if(seen_headers.size()!=state.movements.size()||used_sources!=expected_sources)return bad("GrowthMarketMovementCoverageMismatch");for(const auto& row:out.current.rows()){const auto* actual=c.inventory(row.first);if(!actual||!inventory_equal(row.second,*actual))return bad("GrowthMarketCurrentProjectionMismatch",row.first);}return {true,std::move(out),{}};
}
// 仅原Growth边际算法计算中间价，库存与revision来自已经验证的真实历史投影。
Outcome<GrowthMarketMidpoint> midpoint(const CommonStore& c,const CommonCatalog& common,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,const GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access,const StableId& shop_id,const StableId& item_id,Integer tick,const StableId& boundary){
    if(catalog.selected_version==2||state.version==2)return read_growth_market_history_v2_midpoint(c,common,growth,catalog,state,access,shop_id,item_id,tick,boundary);
    auto source=replay(c,common,growth,catalog,state,access,boundary,tick);if(!source.ok)return {false,{},source.error};const auto* shop=growth.shops.find(shop_id);const auto* item=common.items.find(item_id);if(!shop||!item||std::find(catalog.shop_ids.begin(),catalog.shop_ids.end(),shop_id)==catalog.shop_ids.end()||std::find(growth.tradeable_items.begin(),growth.tradeable_items.end(),item_id)==growth.tradeable_items.end())return {false,{},common_failure("GrowthMarketHistorySelectionInvalid").error};const auto* inv=source.value.before.find(shop->inventory_id);if(!inv)return {false,{},common_failure("GrowthMarketHistorySelectionInvalid").error};Integer stock=0;for(const auto& lot:inv->lots)if(lot.item_id==item_id){if(lot.quantity>INT64_MAX-stock)return {false,{},common_failure("GrowthMarketQuantityOverflow").error};stock+=lot.quantity;}auto value=growth_market_midpoint_from_stock(item->base_price,stock);if(!value.ok)return {false,{},value.error};return {true,{c.state().identity,shop_id,item_id,inv->id,shop->place_id,tick,inv->revision,stock,item->base_price,value.value},{}};
}
}
Status validate_growth_market_history(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,const GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access){if(catalog.selected_version==2||state.version==2)return validate_growth_market_history_v2(c,shared,growth,catalog,state,access);auto r=replay(c,shared,growth,catalog,state,access,{},c.tick());return r.ok?common_success():Status{false,{},r.error};}
Outcome<StableId> record_growth_market_movement_in_candidate(CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access,MarketMovementRecord record){
    if(catalog.selected_version==2||state.version==2)return {false,{},common_failure("GrowthMarketActualFifoCaptureRequired",record.business_fact_id,ErrorKind::unsupported_capability).error};
    for(const auto& row:state.movements.rows())if(row.second.business_fact_id==record.business_fact_id)return {false,{},common_failure("GrowthMarketCauseAlreadyRecorded",record.business_fact_id).error};
    // NPC/Director已经持有Common保存点；这里绝不创建、提交或回滚调用者的点。
    // 本函数的任何失败都使整个外层候选失效，调用者必须连原资源与原业务一起回滚。
    auto id=c.next_id("market_history");if(!id.ok)return id;auto head=c.append_fact({id.value,"growth_market_movement","growth_market_history"});if(!head.ok)return {false,{},head.error};
    if(!state.movements.insert(id.value,std::move(record)))return {false,{},common_failure("DuplicateGrowthMarketMovement",id.value).error};
    auto valid=validate_growth_market_history(c,shared,growth,catalog,state,access);if(!valid.ok)return {false,{},valid.error};return {true,id.value,{}};
}
Outcome<GrowthMarketMidpoint> read_growth_market_history_current(const CommonStore& c,const CommonCatalog& common,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,const GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access,const StableId& shop,const StableId& item){return midpoint(c,common,growth,catalog,state,access,shop,item,c.tick(),{});}
Outcome<GrowthMarketMidpoint> read_growth_market_history_before_shop_result(const CommonStore& c,const CommonCatalog& common,const GrowthCatalog& growth,const GrowthMarketHistoryCatalog& catalog,const GrowthMarketHistoryState& state,const GrowthMarketHistoryAccess& access,const StableId& shop,const StableId& item,Integer tick,const StableId& fact){if(fact.empty())return {false,{},common_failure("GrowthMarketHistoryBoundaryInvalid").error};return midpoint(c,common,growth,catalog,state,access,shop,item,tick,fact);}
}
